{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://semio.tech/schema/os/dev/distribution/component.json",
  "title": "Development Distribution Contracts",
  "$defs": {
    "DistributionDigest": {
      "type": "string",
      "pattern": "^[a-f0-9]{64}$"
    },
    "DistributionPathList": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": {
        "$ref": "#/$defs/DistributionSourceCoordinate"
      }
    },
    "DistributionLayoutChunk": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "kind",
        "source",
        "output"
      ],
      "properties": {
        "kind": {
          "enum": [
            "facade",
            "module"
          ]
        },
        "source": {
          "$ref": "#/$defs/DistributionSourceCoordinate"
        },
        "output": {
          "type": "string",
          "minLength": 1
        }
      }
    },
    "DistributionLayoutAsset": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "kind",
        "source",
        "output"
      ],
      "properties": {
        "kind": {
          "enum": [
            "source",
            "name"
          ]
        },
        "source": {
          "$ref": "#/$defs/DistributionSourceCoordinate"
        },
        "emittedName": {
          "type": "string",
          "minLength": 1
        },
        "output": {
          "type": "string",
          "minLength": 1
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "kind": {
                "const": "name"
              }
            }
          },
          "then": {
            "properties": {
              "emittedName": false
            }
          }
        }
      ]
    },
    "DistributionLayout": {
      "title": "Distribution Layout",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "version",
        "directory",
        "bundles",
        "entry",
        "manifest",
        "chunks",
        "assets"
      ],
      "properties": {
        "version": {
          "const": 1
        },
        "directory": {
          "type": "string",
          "minLength": 1
        },
        "bundles": {
          "type": "string",
          "minLength": 1
        },
        "entry": {
          "type": "object",
          "additionalProperties": false,
          "required": [
            "source",
            "output"
          ],
          "properties": {
            "source": {
              "$ref": "#/$defs/DistributionSourceCoordinate"
            },
            "output": {
              "type": "string",
              "minLength": 1
            }
          }
        },
        "manifest": {
          "type": "string",
          "minLength": 1
        },
        "chunks": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/DistributionLayoutChunk"
          }
        },
        "assets": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/DistributionLayoutAsset"
          }
        }
      }
    },
    "DistributionStaticInputs": {
      "title": "Distribution Static Compiler Inputs",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "version",
        "paths",
        "moduleEntries"
      ],
      "properties": {
        "version": {
          "const": 1
        },
        "paths": {
          "$ref": "#/$defs/DistributionPathList"
        },
        "moduleEntries": {
          "$ref": "#/$defs/DistributionPathList"
        }
      }
    },
    "DistributionManifestInput": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "path",
        "bytes",
        "sha256"
      ],
      "properties": {
        "path": {
          "$ref": "#/$defs/DistributionSourceCoordinate"
        },
        "bytes": {
          "type": "integer",
          "minimum": 0
        },
        "sha256": {
          "$ref": "#/$defs/DistributionDigest"
        }
      }
    },
    "DistributionManifestOutput": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "ownerId",
        "path",
        "bytes",
        "sha256"
      ],
      "properties": {
        "ownerId": {
          "type": "string",
          "minLength": 1
        },
        "path": {
          "$ref": "#/$defs/DistributionSourceCoordinate"
        },
        "bytes": {
          "type": "integer",
          "minimum": 0
        },
        "sha256": {
          "$ref": "#/$defs/DistributionDigest"
        }
      }
    },
    "DistributionManifest": {
      "title": "Distribution Bundle Manifest",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "version",
        "contractId",
        "layoutSha256",
        "inputs",
        "outputs"
      ],
      "properties": {
        "version": {
          "const": 1
        },
        "contractId": {
          "const": "dev-distribution-bundle"
        },
        "layoutSha256": {
          "$ref": "#/$defs/DistributionDigest"
        },
        "inputs": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/DistributionManifestInput"
          }
        },
        "outputs": {
          "type": "array",
          "minItems": 1,
          "items": {
            "$ref": "#/$defs/DistributionManifestOutput"
          }
        }
      }
    },
    "DistributionSourceCoordinate": {
      "type": "string",
      "minLength": 1,
      "pattern": "^(?!/)(?!.*(?:^|/)\\.\\.?(?:/|$))[^\\\\\\u0000-\\u001F:]+$",
      "description": "One canonical production source or artifact coordinate; testing example collection ancestry is refused.",
      "not": {
        "pattern": "(?:^(?:🧫️fixtures|🧫️examples|🧪️fixtures|🧪️examples)(?:/|$)|(?:^|/)(?!🔨️modules/)[^/]+/(?:🧫️fixtures|🧫️examples|🧪️fixtures|🧪️examples)(?:/|$))"
      }
    }
  }
}

{
  "coordinates": [
    {
      "path": "entry.ts",
      "refused": false
    },
    {
      "path": "plumbing/fixtureCount.ts",
      "refused": false
    },
    {
      "path": "🧫️fixtures/cases.json",
      "refused": true
    },
    {
      "path": "os/🧫️fixtures/cases.json",
      "refused": true
    },
    {
      "path": "os/🧪️examples/case.ts",
      "refused": true
    },
    {
      "path": "🔨️modules/🧫️fixtures/module.ts",
      "refused": false
    },
    {
      "path": "🔨️modules/🧫️fixtures/🧫️fixtures/case.json",
      "refused": true
    }
  ],
  "closures": [
    {
      "id": "inline-test-import",
      "files": {
        "entry.ts": "import { identity } from \"./normal.ts\"; export { identity }; if (import.meta.vitest) { const examples = await import(\"./🧫️fixtures/cases.json\"); console.log(examples); }",
        "normal.ts": "export const identity = \"production\";",
        "🧫️fixtures/cases.json": "{\"expected\":\"testing\"}"
      },
      "entries": [
        "entry.ts"
      ],
      "paths": [
        "entry.ts",
        "normal.ts"
      ],
      "refused": false
    },
    {
      "id": "live-fixture-import",
      "files": {
        "entry.ts": "import examples from \"./🧫️fixtures/cases.json\"; export { examples };",
        "🧫️fixtures/cases.json": "{\"expected\":\"testing\"}"
      },
      "entries": [
        "entry.ts"
      ],
      "refused": true
    },
    {
      "id": "fixture-entry",
      "files": {
        "🧫️examples/entry.ts": "export const identity = \"testing\";"
      },
      "entries": [
        "🧫️examples/entry.ts"
      ],
      "refused": true
    },
    {
      "id": "genuine-fixture-domain-word",
      "files": {
        "entry.ts": "import { fixtureCount } from \"./plumbing.ts\"; export { fixtureCount };",
        "plumbing.ts": "export const fixtureCount = 4;"
      },
      "entries": [
        "entry.ts"
      ],
      "paths": [
        "entry.ts",
        "plumbing.ts"
      ],
      "refused": false
    },
    {
      "id": "genuine-framework-fixtures-module",
      "files": {
        "entry.ts": "export { identity } from \"./🔨️modules/🧫️fixtures/module.ts\";",
        "🔨️modules/🧫️fixtures/module.ts": "export const identity = \"framework\";"
      },
      "entries": [
        "entry.ts"
      ],
      "paths": [
        "entry.ts",
        "🔨️modules/🧫️fixtures/module.ts"
      ],
      "refused": false
    },
    {
      "id": "alternate-testing-collection",
      "files": {
        "entry.ts": "export { identity } from \"./🧪️examples/example.ts\";",
        "🧪️examples/example.ts": "export const identity = \"testing\";"
      },
      "entries": [
        "entry.ts"
      ],
      "refused": true
    },
    {
      "id": "physical-fixture-alias",
      "files": {
        "entry.ts": "export { default as value } from \"./live.json\";",
        "🧫️fixtures/cases.json": "{\"expected\":\"testing\"}"
      },
      "links": {
        "live.json": "🧫️fixtures/cases.json"
      },
      "entries": [
        "entry.ts"
      ],
      "refused": true
    },
    {
      "id": "eliminated-static-test-use",
      "files": {
        "entry.ts": "import examples from \"./🧫️fixtures/cases.json\"; export const identity = \"production\"; if (import.meta.vitest) console.log(examples);",
        "🧫️fixtures/cases.json": "{\"expected\":\"testing\"}"
      },
      "entries": [
        "entry.ts"
      ],
      "refused": true
    },
    {
      "id": "type-only-import",
      "files": {
        "entry.ts": "import type { Example } from \"./🧫️fixtures/example.ts\"; export const identity = \"production\";",
        "🧫️fixtures/example.ts": "export type Example = { expected: string };"
      },
      "entries": [
        "entry.ts"
      ],
      "paths": [
        "entry.ts"
      ],
      "refused": false
    },
    {
      "id": "live-fixture-side-effect",
      "files": {
        "entry.ts": "import \"./🧫️fixtures/example.ts\"; export const identity = \"production\";",
        "🧫️fixtures/example.ts": "console.log(\"testing\");"
      },
      "entries": [
        "entry.ts"
      ],
      "refused": true
    }
  ]
}

import { expect, test } from "bun:test";
import Ajv from "ajv";
import { build, transform } from "esbuild";
import { mkdirSync, mkdtempSync, readFileSync, rmSync, symlinkSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { distributionStaticSourcePaths } from "../🟦️.ts";
import { DISTRIBUTION_LAYOUT, parseDistributionManifest, parseDistributionStaticInputs } from "../../🟦️.ts";

const examples = JSON.parse(readFileSync(join(import.meta.dir, "../🧫️fixtures/🔣️.json"), "utf8"));
const schema = JSON.parse(readFileSync(join(import.meta.dir, "../../🧬️schema/🔣️.json"), "utf8"));

test("distribution production coordinates refuse testing collections with genuine schema parity", () => {
  const validate = new Ajv({ strict: true }).addSchema(schema).getSchema(`${schema.$id}#/$defs/DistributionSourceCoordinate`)!;
  for (const row of examples.coordinates) {
    expect(validate(row.path), row.path).toBe(!row.refused);
    const staticInput = () => parseDistributionStaticInputs({ version: 1, paths: [row.path], moduleEntries: [row.path] });
    const manifest = () => parseDistributionManifest({ version: 1, contractId: "dev-distribution-bundle", layoutSha256: "a".repeat(64), inputs: [{ path: row.path, bytes: 0, sha256: "a".repeat(64) }], outputs: [{ ownerId: DISTRIBUTION_LAYOUT.entry.output, path: DISTRIBUTION_LAYOUT.entry.output, bytes: 0, sha256: "a".repeat(64) }] }, DISTRIBUTION_LAYOUT);
    if (row.refused) { expect(staticInput).toThrow(/fixture|testing/iu); expect(manifest).toThrow(/fixture|testing/iu); }
    else { expect(staticInput().paths).toEqual([row.path]); expect(manifest().inputs[0]!.path).toBe(row.path); }
  }
});

test("distribution source closure excludes inline tests and refuses actual fixture inputs", async () => {
  const output = process.env.SEMIO_TEST_ARTIFACT_DIR;
  if (!output) throw Error("Explicit ticket output required for distribution source verification");
  mkdirSync(output, { recursive: true });
  const work = mkdtempSync(join(output, "distribution-source-"));
  const validate = new Ajv({ strict: true }).addSchema(schema).getSchema(`${schema.$id}#/$defs/DistributionSourceCoordinate`)!;
  try {
    for (const row of examples.closures) {
      const root = join(work, row.id);
      for (const [path, source] of Object.entries(row.files) as [string, string][]) { const target = join(root, path); mkdirSync(dirname(target), { recursive: true }); writeFileSync(target, source); }
      for (const [path, target] of Object.entries(row.links ?? {}) as [string, string][]) symlinkSync(target, join(root, path));
      const actual = () => distributionStaticSourcePaths(root, row.entries);
      const oracle = await build({ absWorkingDir: root, entryPoints: row.entries, bundle: true, write: false, format: "esm", platform: "browser", metafile: true, define: { "import.meta.vitest": "undefined" }, logLevel: "silent", plugins: [{ name: "independent-production-exclusion", setup(compiler) { compiler.onLoad({ filter: /\.[cm]?[jt]sx?$/ }, async args => ({ contents: (await transform(readFileSync(args.path, "utf8"), { loader: args.path.endsWith("tsx") ? "tsx" : args.path.endsWith("ts") ? "ts" : "js", define: { "import.meta.vitest": "undefined" }, minifySyntax: true })).code, loader: "js" })); } }] });
      const oraclePaths = Object.keys(oracle.metafile!.inputs).map(path => relative(root, join(root, path)).replaceAll("\\", "/")).sort((a, b) => Buffer.compare(Buffer.from(a), Buffer.from(b)));
      expect(oraclePaths.some(path => !validate(path)), row.id).toBe(row.refused);
      if (row.refused) { await expect(actual()).rejects.toThrow(/fixture|testing/iu); continue; }
      const paths = await actual();
      expect(paths, row.id).toEqual([...row.paths].sort((a: string, b: string) => Buffer.compare(Buffer.from(a), Buffer.from(b))));
      expect(paths, row.id).toEqual(oraclePaths);
    }
    console.log("[DEBUG] actual production source closure compared with esbuild; physical fixture aliases refused");
  } finally { rmSync(work, { recursive: true, force: true }); }
});

test("distribution actual static producer inventory contains no testing collections", async () => {
  const root = process.env.REPO_ROOT;
  if (!root) throw Error("Actual repository root required for distribution source verification");
  const authority = parseDistributionStaticInputs(JSON.parse(readFileSync(join(import.meta.dir, "../../🔗️inputs.json"), "utf8")));
  const paths = await distributionStaticSourcePaths(root, authority.moduleEntries);
  const validate = new Ajv({ strict: true }).addSchema(schema).getSchema(`${schema.$id}#/$defs/DistributionSourceCoordinate`)!;
  expect(paths.length).toBeGreaterThan(authority.moduleEntries.length);
  for (const path of paths) expect(validate(path), path).toBe(true);
  console.log(`[DEBUG] actual distribution static producer inventory: ${paths.length} source/package inputs, zero testing collection inputs`);
});
